#[path="../crates/battle-core/src/ai.rs"]mod ai;
use ai::*;use std::io::{self,BufRead,Write};
fn manual(v:usize)->ManualCast{match v{0=>ManualCast::Undefined,1=>ManualCast::Null,2=>ManualCast::False,3=>ManualCast::Cast,4=>ManualCast::Trigger,_=>panic!()}}
fn mcode(v:ManualCast)->usize{match v{ManualCast::Undefined=>0,ManualCast::Null=>1,ManualCast::False=>2,ManualCast::Cast=>3,ManualCast::Trigger=>4}}
fn opt(v:Option<usize>)->String{v.map(|x|x.to_string()).unwrap_or_else(||"null".into())}
fn state(s:&SkillSelection)->String{format!("{{\"manual\":{},\"manualSkill\":{},\"currentSkill\":{},\"turnbased\":{},\"target\":{},\"canCast\":{},\"willCast\":{},\"list\":{},\"lists\":{:?}}}",s.manual,opt(s.manual_skill),opt(s.current_skill),s.turnbased,opt(s.target),mcode(s.can_cast_manual),s.will_cast_manual,s.list,s.lists)}
struct Hooks{calls:Vec<String>,answers:Vec<bool>,mask:usize,count:usize,n:usize}
impl Hooks{fn call(&mut self,s:&mut SkillSelection,kind:&str,id:Option<usize>,target:Option<usize>)->bool{let before=state(s);let answer=self.answers[self.count%self.answers.len()];self.count+=1;if self.mask&1!=0{s.manual=!s.manual}if self.mask&2!=0{s.turnbased=!s.turnbased}if self.mask&4!=0{s.target=Some((s.target.unwrap_or(0)+1)%7)}if self.mask&8!=0{s.list=1-s.list}if self.mask&16!=0{let list=self.count%2;let index=self.count%self.n;s.lists[list][index]=(s.lists[list][index]+1)%self.n;}if self.mask&32!=0{s.current_skill=Some((s.current_skill.unwrap_or(0)+1)%self.n)}if self.mask&64!=0{s.manual_skill=Some((s.manual_skill.unwrap_or(0)+1)%self.n)}self.calls.push(format!("{{\"kind\":\"{}\",\"skill\":{},\"target\":{},\"before\":{},\"after\":{},\"answer\":{}}}",kind,opt(id),opt(target),before,state(s),answer));answer}}
impl SkillHooks for Hooks{
fn can_cast_with_target(&mut self,s:&mut SkillSelection,id:usize,t:Option<usize>)->bool{self.call(s,"can",Some(id),t)}fn can_cast_turnbased_target(&mut self,s:&mut SkillSelection,id:usize,t:Option<usize>)->bool{self.call(s,"canTB",Some(id),t)}fn will_cast(&mut self,s:&mut SkillSelection,id:usize)->bool{self.call(s,"will",Some(id),None)}fn cast_skill_special_turnbased(&mut self,s:&mut SkillSelection){self.call(s,"specialTB",None,None);}fn can_trigger(&mut self,s:&mut SkillSelection,id:usize)->bool{self.call(s,"canTrigger",Some(id),None)}fn will_trigger(&mut self,s:&mut SkillSelection,id:usize)->bool{self.call(s,"willTrigger",Some(id),None)}}
fn int(i:&mut std::str::SplitWhitespace<'_>)->usize{i.next().unwrap().parse().unwrap()}
fn main()->io::Result<()>{let input=io::stdin();let mut out=io::BufWriter::new(io::stdout().lock());for line in input.lock().lines(){let line=line?;let mut i=line.split_whitespace();let kind=int(&mut i);let n=int(&mut i);let manual_flag=int(&mut i)!=0;let ms=int(&mut i);let cs=int(&mut i);let tb=int(&mut i)!=0;let cast=manual(int(&mut i));let will=int(&mut i)!=0;let target=int(&mut i);let list=int(&mut i);let mut lists=vec![];for _ in 0..2{lists.push((0..n).map(|_|int(&mut i)).collect());}let mask=int(&mut i);let length=int(&mut i);let answers=(0..length).map(|_|int(&mut i)!=0).collect();let mut s=SkillSelection{lists,list,manual:manual_flag,manual_skill:if ms==n{None}else{Some(ms)},current_skill:if cs==n{None}else{Some(cs)},turnbased:tb,target:if target==7{None}else{Some(target)},can_cast_manual:cast,will_cast_manual:will};let mut h=Hooks{calls:vec![],answers,mask,count:0,n};let result=if kind==0{opt(find_skill_to_cast(&mut s,&mut h))}else{if check_trigger(&mut s,&mut h).is_some(){"\"true\"".into()}else{"\"undefined\"".into()}};writeln!(out,"{{\"result\":{},\"state\":{},\"calls\":[{}]}}",result,state(&s),h.calls.join(","))?;}out.flush()}
